// Ultrawide value index — record JAH-GPC-ULTRAWIDE-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"refresh_hz": 144, "res_mp": 5.0, "price_usd": 500};
var value = (m.refresh_hz*m.res_mp/m.price_usd*100);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-ULTRAWIDE-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-ULTRAWIDE-000001|' + value.toFixed(2) + ' display index');

